package br.edu.insper.tarefas;
import jakarta.persistence.*; import java.time.LocalDateTime;
@Entity @Table(name="tasks") public class Task { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @Column(nullable=false) private String title; private String description; @Enumerated(EnumType.STRING) @Column(nullable=false) private TaskStatus status; @Column(nullable=false) private LocalDateTime createdAt; protected Task(){} public Task(String title,String description){this.title=title;this.description=description;status=TaskStatus.PENDING;createdAt=LocalDateTime.now();} public Long getId(){return id;} public String getTitle(){return title;} public String getDescription(){return description;} public TaskStatus getStatus(){return status;} public LocalDateTime getCreatedAt(){return createdAt;} public void update(String title,String description,TaskStatus status){this.title=title;this.description=description;this.status=status;} }
